        battle.add_unit(ally, Position(3, 1))
        payload = {"type": "skill", "unit_id": soldier.unit_id, "skill_code": "machine_gun", "cells": [{"x": x, "y": 1} for x in range(2, 5)]}
        queued = battle.build_queued_action(payload)
