                actor.mana_points = cap - 0.5
                self.assertEqual(actor.gain_mana_points(2), 0.5)
                self.assertEqual(actor.mana_points, cap)
                self.assertEqual(actor.gain_mana_points(1), 0)
                actor.spend_mana_points(1)
