        self.assertLess(r20_weather_cast_score(battle, actor, "wetland_grassland", profile), 0)
        actor.position, enemy.position = Position(0, 0), Position(17, 13)
        self.assertLess(r20_weather_cast_score(battle, actor, "wetland_grassland", profile), 0)
